#include <time.h>      // radial Quick Access: favorite + LRU timestamps

// Round 12 HD diagnosis: NOVA_DEBUG=1 appends draw-path decisions to
// nova_debug.txt (thumb results, icon captures, scaler failures).
static void ndbg(const char* fmt, ...) {
    if (!getenv("NOVA_DEBUG")) return;
    static FILE* f = NULL;
    if (!f) f = fopen("nova_debug.txt", "a");
    if (!f) return;
    va_list ap;
    va_start(ap, fmt);
    vfprintf(f, fmt, ap);
    va_end(ap);
    fflush(f);
}

// ------------------------------------------------------------
// Design constants (96 DPI). Every one of them goes through
// SC() so the whole UI scales on 4K / high-DPI displays.
// ------------------------------------------------------------
#define APP_NAME       "Nova File"
#define WIN_W          1280
#define WIN_H           720
#define TOOLBAR_H        72   // two rows: tabs (34) + nav/breadcrumb (38)
#define TAB_H            34
#define NAV_H            38
#define STATUS_H         34   // bottom bar: path + size slider + view button
#define SIDEBAR_W       240
#define LIST_HEAD_H      26
#define ROW_H            26
#define TEXT_H           16
#define CELL_W          124
#define CELL_H          142
#define THUMB_BOX        80
#define SCROLL_W         14
#define BTN_H            28
#define NAV_BTN_COUNT     4    // back / forward / up / refresh (icons)
#define TAB_MAX           20    // hard cap on open tabs, workspace-wide
#define MENU_MAX          9
// Right-click menu: one flat row array big enough for the full Explorer
// style menu (root rows + every submenu's children live in the same array).
#define CTX_MAX          96
#define CRUMB_MAX        24
#define MAX_HISTORY      32

typedef struct {
    char current_path[1024];
    DirEntry* entries;
    size_t count;
    int* view;
    size_t view_count;
    int selected;
    int scroll;
    int view_mode;
    int sort_key;
    int sort_dir;
    // Per-pane navigation stacks. (The old `int history` here was 131 KB
    // of dead weight whose memcpy over-read g_app.history by 96 KB, and
    // fwd_count pointed into ANOTHER pane's forward targets.)
    char history[MAX_HISTORY][1024];
    int history_count;
    char fwd_history[MAX_HISTORY][1024];
    int fwd_count;
    char addr_buf[1024];
    char search_buf[128];       // per-pane filter (switching panes keeps it)
    bool search_focused;
    // NOTE: no tab/workspace state and no theme field here on purpose -
    // tabs are workspaces (owned by the global g_ws[] list) and `light`
    // is a single global setting.
} FolderView;
 typedef struct { int x, y, w, h; } RectI;

typedef enum { PN_LEAF, PN_SPLIT_V, PN_SPLIT_H } PaneKind;
typedef struct Pane Pane;
struct Pane {
    PaneKind kind;
    float ratio;              // 0..1 split position (internal nodes)
    Pane* left;
    Pane* right;
    RectI  rect;              // computed content rect (leaf)
    RectI  region;            // content area this node divides (split nodes)
    FolderView folder;        // leaf content
};

// Big enough for a FULL zoomed-out screen: at 15% one window holds ~500
// cells, and a smaller cache made every frame evict and re-fetch icons -
// folders kept their icons while files never kept theirs (the "white
// papers load forever" bug), and the constant churn made the small-zoom
// grid look like it was "running".
#define ICON_CACHE     1024
#define THUMB_BMP_CACHE 1024  // shell thumbnails (path + size keyed)
#define RECENT_MAX        4    // fixed slots in the sidebar (never shifts)
#define BOOKMARK_MAX      8
#define SIDE_MAX         48
#define THIS_PC        "This PC"   // virtual folder: one row per drive

static float g_dpi = 1.0f;                      // 1.0 = 96 DPI, 2.0 = 4K
#define SC(v) ((int)((v) * g_dpi + 0.5f))

// Pane chrome: every tiled pane gets a title strip above its list
// (folder path + close [x] + drag handle); workspace tabs never shrink
// below TAB_MIN_W - they scroll instead of vanishing.
#define PANE_TITLE_H      SC(24)
#define TAB_MIN_W         SC(128)

// View modes, in the order of the "Details" popup menu:
// Details | List | Tree | Icons | XL icons.
typedef enum {
    MODE_DETAILS = 0, MODE_LIST = 1, MODE_TREE = 2, MODE_ICONS = 3,
    MODE_XL = 4, VIEW_MENU_MAX = 5
} ViewMode;
typedef enum { SORT_NAME = 0, SORT_SIZE = 1, SORT_DATE = 2, SORT_TYPE = 3 } SortKey;
enum { SIDE_HEAD = 0, SIDE_ITEM = 1, SIDE_SPACER = 2 };


// ------------------------------------------------------------
// Palette - File Pilot style dark blue grey (+ light variant)
// ------------------------------------------------------------
typedef struct {
    Color bg, panel, toolbar, btn, btn_hover;
    Color head, row_alt, row_hover, selected;
    Color text, dim, accent, border;
    Color folder, file, scroll, field, paper;
    // Search-match highlight (the box behind the matching characters).
    // Deliberately NEUTRAL - a muted charcoal in dark mode, a soft gray in
    // light mode - so a match never reads as a bright saturated block, and
    // the matched glyphs switch to hl_fg so an amber folder name or a blue
    // selection can never tint the highlight. Every renderer reads these
    // tokens; nothing hardcodes a match colour.
    Color hl_bg, hl_fg;
} Palette;

