typedef struct {
    PlatformAPI* platform;
    RendererContext* renderer;
    Theme* theme;
    void* hwnd;

    char current_path[1024];
    DirEntry* entries;
    size_t count;

    int* view;
    size_t view_count;

    int selected;
    int scroll;

    char addr_buf[1024];
    bool addr_focused;
    char search_buf[128];
    bool search_focused;
    // Caret + selection for the two text fields (byte indices into the
    // buffer). anchor == caret means no selection; a selection spans the
    // range between them. UTF-8 aware: movement steps whole characters.
    int addr_caret, addr_anchor;
    int search_caret, search_anchor;

    int view_mode;           // ViewMode
    int sort_key;            // SortKey
    int sort_dir;            // +1 / -1
    bool light;

    char history[MAX_HISTORY][1024];
    int history_count;
    char fwd_history[MAX_HISTORY][1024];
    int fwd_count;

    bool menu_open;
    bool view_menu_open;     // Details (Tree / List / Icons / XL) popup

    char status_msg[256];
    unsigned long frame;
    bool running;
} App;

