// Drag-to-tile state: press in a pane's body, drag to a drop zone.
// Zones are the halves / corners of the pane under the cursor; the
// center (and anything outside the panes) cancels the drop.
typedef enum {
    DZ_NONE = 0, DZ_LEFT, DZ_RIGHT, DZ_TOP, DZ_BOTTOM,
    DZ_TL, DZ_TR, DZ_BL, DZ_BR, DZ_CENTER
} DropZone;
static bool g_drag_split = false;
static bool g_drag_split_armed = false;   // pressed in a pane, might drag
static int g_drag_start_x = 0, g_drag_start_y = 0;
static int g_sort_pending = -1;         // held header press: sort column,
                                        // applied when the click completes
static Pane* g_drag_pane = NULL;        // the pane captured at drag start
static Pane* g_drop_target = NULL;      // currently highlighted drop zone
static RectI g_drop_rect = {0,0,0,0};    // rect the drop would create
static RectI g_drop_disp = {0,0,0,0};    // animated (lerped) display rect
static float g_drop_fade = 0.f;          // preview fade-in 0..1
static int g_drop_zone = DZ_NONE;        // DropZone under the cursor
static bool g_drop_active = false;      // a valid drop zone is highlighted
static RectI g_content = {0,0,0,0};      // window content rect (layout root)

// ---- docking indicator chips (the visual chooser, Phase 3) --------
// Dashed cells [LEFT|CENTER|RIGHT] through the pane's middle plus
// [TOP]/[BOTTOM] near its edges - the reference's signature overlay.
// Geometry only (no state, no input): the zone machine above still
// decides every drop, the chips only DRAW it; keeping layout pure lets
// the selftest assert bounds and non-overlap directly.
#define DOCK_CHIP_N 5
// out[] order: 0 LEFT, 1 CENTER, 2 RIGHT, 3 TOP, 4 BOTTOM
static bool dock_chip_layout(const RectI* r, RectI out[DOCK_CHIP_N]) {
    if (!r || r->w < SC(150) || r->h < SC(120)) return false;  // too small
    int gap = SC(6), cw = SC(46), ch = SC(28);
    int maxw = (r->w - SC(24) - 2 * gap) / 3;
    if (cw > maxw) cw = maxw;                  // shrink instead of overflow
    if (cw < SC(20)) return false;
    int cx = r->x + r->w / 2, cy = r->y + r->h / 2;
    int trio_w = 3 * cw + 2 * gap;
    int x0 = cx - trio_w / 2, y0 = cy - ch / 2;
    out[0] = (RectI){x0, y0, cw, ch};                             // LEFT
    out[1] = (RectI){x0 + cw + gap, y0, cw, ch};                  // CENTER
    out[2] = (RectI){x0 + 2 * (cw + gap), y0, cw, ch};            // RIGHT
    int tx = cx - cw / 2;
    int ty = r->y + PANE_TITLE_H + SC(8);      // under the pane title strip
    if (ty + ch > y0 - SC(4)) ty = y0 - SC(4) - ch;   // never the trio
    if (ty < r->y + SC(2)) ty = r->y + SC(2);
    out[3] = (RectI){tx, ty, cw, ch};                           // TOP
    ty = r->y + r->h - SC(8) - ch;              // above the pane's bottom
    if (ty < y0 + ch + SC(4)) ty = y0 + ch + SC(4);    // never the trio
    if (ty + ch > r->y + r->h - SC(2)) ty = r->y + r->h - SC(2) - ch;
    out[4] = (RectI){tx, ty, cw, ch};                          // BOTTOM
    for (int i = 0; i < DOCK_CHIP_N; i++) {      // hard pane boundary
        if (out[i].x < r->x) out[i].x = r->x;
        if (out[i].y < r->y) out[i].y = r->y;
        if (out[i].x + out[i].w > r->x + r->w)
            out[i].x = r->x + r->w - out[i].w;
        if (out[i].y + out[i].h > r->y + r->h)
            out[i].y = r->y + r->h - out[i].h;
    }
    return true;
}

// Which cells light for the zone under the cursor: exact match, or BOTH
// edge cells when a corner quarter is lit (TL lights Left+Top, ...), so
// the chooser keeps tracking the pointer smoothly around the pane.
static bool dock_zone_lights(int zone, int chip_z) {
    if (zone == DZ_NONE) return false;
    if (zone == chip_z) return true;
    switch (zone) {
        case DZ_TL: return chip_z == DZ_LEFT  || chip_z == DZ_TOP;
        case DZ_TR: return chip_z == DZ_RIGHT || chip_z == DZ_TOP;
        case DZ_BL: return chip_z == DZ_LEFT  || chip_z == DZ_BOTTOM;
        case DZ_BR: return chip_z == DZ_RIGHT || chip_z == DZ_BOTTOM;
        default: return false;
    }
}

// ============================================================
// Right-click context menu - ONE data-driven model.
// A menu is a flat array of rows; a submenu row references a range
// of child rows. Everything the menu shows is built by ctx_build()
// for the exact target (file / folder / multi / mixed / background),
// so an action can never appear where it does not make sense.
// ============================================================

typedef enum { CTX_SEP = 0, CTX_ITEM, CTX_SUB } CtxKind;

typedef struct CtxRow {
    int kind;              // CtxKind
    const char* label;     // NULL for a separator
    const char* hint;      // right-aligned shortcut hint (NULL = none)
    int cmd;               // CTX_CMD_* (items only)
    bool enabled;          // false = drawn dim, not clickable
    int sub;               // CTX_SUB: index of the first child row
    int sub_n;             //          number of child rows
} CtxRow;

typedef enum {
    CTX_CMD_NONE = -1,
    // file / folder
    CTX_CMD_OPEN,
    CTX_CMD_OPEN_TAB,
    CTX_CMD_OPEN_PANE,
    CTX_CMD_OPEN_WITH,
    CTX_CMD_SHARE,
    CTX_CMD_SEND_TO,
    CTX_CMD_CUT,
    CTX_CMD_COPY,
    CTX_CMD_PASTE,
    CTX_CMD_PASTE_SHORTCUT,
    CTX_CMD_COPY_PATH,
    CTX_CMD_CREATE_SHORTCUT,
    CTX_CMD_RENAME,
    CTX_CMD_DELETE,
    CTX_CMD_PROPERTIES,
    // New >
    CTX_CMD_NEW,
    CTX_CMD_NEW_FOLDER,
    CTX_CMD_NEW_TEXT,
    // Sort by >
    CTX_CMD_SORT_BY,
    CTX_CMD_SORT_NAME,
    CTX_CMD_SORT_DATE,
    CTX_CMD_SORT_TYPE,
    CTX_CMD_SORT_SIZE,
    // Group by >
    CTX_CMD_GROUP_BY,
    CTX_CMD_GROUP_NONE,
    CTX_CMD_GROUP_NAME,
    CTX_CMD_GROUP_DATE,
    CTX_CMD_GROUP_TYPE,
    CTX_CMD_GROUP_SIZE,
    // View >
    CTX_CMD_VIEW,
    CTX_CMD_VIEW_XL,
    CTX_CMD_VIEW_ICONS,
    CTX_CMD_VIEW_MEDIUM,
    CTX_CMD_VIEW_SMALL,
    CTX_CMD_VIEW_LIST,
    CTX_CMD_VIEW_DETAILS,
    CTX_CMD_REFRESH,
    // custom folder thumbnail (folders only)
    CTX_CMD_SET_THUMB,
    CTX_CMD_CHANGE_THUMB,
    CTX_CMD_REMOVE_THUMB,
    // tab strip (the reference app's right-click menu on a tab)
    CTX_CMD_TAB_SHIFT_L,
    CTX_CMD_TAB_SHIFT_R,
    CTX_CMD_TAB_DUP,
    CTX_CMD_TAB_DUP_WIN,
    CTX_CMD_TAB_CLOSE,
    CTX_CMD_TAB_CLOSE_OTHERS,
    CTX_CMD_TAB_CLOSE_LEFT,
    CTX_CMD_TAB_CLOSE_RIGHT,
    CTX_CMD_TAB_CLOSE_ALL,
    // sidebar entries
    CTX_CMD_SIDE_OPEN,
    CTX_CMD_SIDE_OPEN_TAB,
    CTX_CMD_SIDE_OPEN_PANE,
    CTX_CMD_SIDE_STAR,
} CtxCmd;

static CtxRow g_m[CTX_MAX];    // the open menu's root rows + submenu children
static int    g_m_n;
static int    g_m_open;        // index of the open submenu row, -1 = none
// The ROOT panel's own view of g_m: which rows it shows and how many.
// A submenu's children live in g_m right behind their parent (one flat
// array, one scan, no second structure to keep in sync) but are only
// ever SHOWN in the submenu panel - so the panel's height, its row
// rectangles, the drawing and the hit-testing all read these, and what
// is drawn can never drift from what is clickable.
static int    g_m_root[CTX_MAX];
static int    g_m_root_n;
static void   ctx_map_roots(void);
static int    ctx_root_ord(int row);
static bool   g_ctx_open = false;
static int    g_ctx_focus = -1;       // keyboard focus: ROOT row ordinal
static int    g_ctx_sub_focus = -1;   // keyboard focus: child ordinal
static int    g_ctx_x = 0, g_ctx_y = 0;   // anchor point of the press
static int    g_ctx_view = -1;            // view index of the target row
static bool   g_ctx_bg = false;           // true = background (empty space) menu
static int    g_ctx_tab = -1;             // right-clicked TAB index (tab menu)
// The sidebar menu acts on a SNAPSHOT: the sidebar rebuilds itself
// (recents come and go, bookmarks change) while its menu is open.
static char   g_ctx_side_path[1024];
static char   g_ctx_side_label[128];
static bool   g_ctx_side_file;

// ---- multi-selection ----
// g_app.selected stays the PRIMARY row (the last one clicked); g_sel[] is
// the whole set the operations act on. Ctrl+click toggles a row, Shift+
// click takes the range, Ctrl+A takes everything.
#define SEL_MAX 8192
static int g_sel[SEL_MAX];
static int g_sel_n;

static void sel_clear(void) { g_sel_n = 0; }
static bool sel_contains(int vi) {
    for (int i = 0; i < g_sel_n; i++)
        if (g_sel[i] == vi) return true;
    return false;
}
static void sel_add(int vi) {
    if (g_sel_n < SEL_MAX && !sel_contains(vi)) g_sel[g_sel_n++] = vi;
}
static void sel_remove(int vi) {
    for (int i = 0; i < g_sel_n; i++)
        if (g_sel[i] == vi) {
            for (int j = i; j + 1 < g_sel_n; j++) g_sel[j] = g_sel[j + 1];
            g_sel_n--;
            return;
        }
}
// The paths of the whole selection, in view order. Caller frees with
// sel_paths_free(). With no stored set it falls back to the row the menu
// was opened on, so exactly one resolver decides what "the selection"
// means for every command.
static DirEntry* ctx_target(void);
static char** sel_paths(int* out_count) {
    *out_count = 0;
    if (g_sel_n <= 0) {
        // No stored set (a menu opened straight from the keyboard): the
        // right-clicked target IS the selection - one resolver for every
        // command, so no action can silently act on nothing.
        DirEntry* t = ctx_target();
        if (!t) return NULL;
        char** one = (char**)calloc(1, sizeof(char*));
        if (!one) return NULL;
        one[0] = _strdup(t->path);
        if (!one[0]) { free(one); return NULL; }
        *out_count = 1;
        return one;
    }
    char** p = (char**)calloc((size_t)g_sel_n, sizeof(char*));
    if (!p) return NULL;
    for (int i = 0; i < g_sel_n; i++) {
        int vi = g_sel[i];
        if (vi < 0 || (size_t)vi >= g_app.view_count) continue;
        int ei = g_app.view[vi];
        if (ei < 0 || (size_t)ei >= g_app.count) continue;
        p[(*out_count)++] = _strdup(g_app.entries[ei].path);
    }
    return p;
}
static void sel_paths_free(char** p, int n) {
    if (!p) return;
    for (int i = 0; i < n; i++) free(p[i]);
    free(p);
}

static void pane_free(Pane* p);

// ------------------------------------------------------------
// WORKSPACES (top-level tabs)
// One tab in the toolbar IS one workspace: its own pane tree, its own
// active pane, and through the leaves its own folders / history /
// scroll / selection. g_ws[] is the single source of truth for tab
// state (the old g_app.tab_paths[] copy and the per-pane copy in
// FolderView are gone). While a workspace is live, g_pane_root /
// g_active_pane point INTO it and are the authoritative values; the
// stored root/active of other workspaces stay untouched because only
// the current workspace ever mutates. Tab labels are DERIVED from the
// active pane's path (ws_path), so there is no second copy to go stale.
// ------------------------------------------------------------
typedef struct {
    Pane* root;               // layout tree (one leaf when freshly made)
    Pane* active;             // active leaf (always inside root)
} Workspace;

static Workspace g_ws[TAB_MAX];
static int g_ws_n = 0;
static int g_ws_cur = 0;
static int g_ws_last = -1;          // previously shown workspace (flip target
                                    // when the CURRENT tab is dragged)

// ------------------------------------------------------------
// DRAG SOURCES (spec: one explicit source per gesture, never shared)
// TAB_DRAG  - a TOP TAB  -> may absorb/split or reorder
// PANE_DRAG - a pane title strip -> may MOVE a pane into a drop zone
// RESIZE_DRAG - a divider's 3-dot handle -> may only change a ratio
// FOLDER_DRAG - a row in the file area -> Explorer only, NEVER layout
// Only the flag belonging to the armed source is ever consulted by its
// gesture handler, and a folder row can never raise a layout flag.
// ------------------------------------------------------------
typedef enum {
    DRAG_NONE = 0,
    DRAG_TAB,      // g_tab_armed / g_tab_drag
    DRAG_PANE,     // g_drag_split_armed / g_drag_split
    DRAG_RESIZE,   // g_splitter_drag
    DRAG_FOLDER    // row press: nothing layout-related may start
} DragSource;
static DragSource g_drag_src = DRAG_NONE;

// Reordering drag state (press a tab, move >5px, drop on a slot).
static bool g_tab_armed = false;      // pressed on a tab, below threshold
static bool g_tab_drag = false;       // threshold passed: reordering now
static bool g_tab_flipped = false;    // dragged the CURRENT tab over content
                                      // -> view flipped, restore on cancel
static int g_tab_arm_x = 0, g_tab_arm_y = 0;
static int g_tab_drag_idx = 0;        // workspace being reordered
static int g_tab_drag_x = 0;          // live cursor x (ghost + slot preview)
static int g_tab_drag_off = 0;        // grab offset inside the tab
static int g_tab_scroll = 0;          // strip scroll (only when overflowing)

// Live accessors: for the current workspace the globals ARE the state.
static Pane* ws_root(int i) {
    if (i < 0 || i >= g_ws_n) return NULL;
    return (i == g_ws_cur) ? g_pane_root : g_ws[i].root;
}
static Pane* ws_active(int i) {
    if (i < 0 || i >= g_ws_n) return NULL;
    return (i == g_ws_cur) ? g_active_pane : g_ws[i].active;
}
// Tab icon + label source: the workspace's active pane folder.
static const char* ws_path(int i) {
    Pane* a = ws_active(i);
    if (!a || a->kind != PN_LEAF || !a->folder.current_path[0]) return "";
    return a->folder.current_path;
}
// Where a tab dropped at client x would land (insertion slot, 0..n).
static int tab_slot_at(const Layout* L, int x) {
    int slot = 0;
    for (int i = 0; i < L->tab_drawn; i++) {
        const RectI* r = &L->tab_rects[i];
        if (x > r->x + r->w / 2) slot = i + 1;
    }
    return slot;
}

// Is (x, y) on the TOP TAB strip itself? Input (the tab drag) and drawing
// (the reorder insertion bar + ghost) share this one test, so the reorder
// chrome can never be drawn while the cursor is over Explorer content -
// there the split drop zones take over instead (spec: zones appear only
// while dragging a top tab, and only over another view's area).
static bool tab_strip_pt(const Layout* L, int x, int y) {
    if (!L) return false;
    return y >= L->toolbar.y && y < L->toolbar.y + SC(TAB_H) &&
           x >= L->tabs_x && x <= L->tabs_x + L->tab_area;
}

// ---- async thumbnail pipeline (worker thread + disk cache) ------------
// paint() may only QUEUE thumbnail/OLE work: one background thread does
// the slow shell calls and writes the result to the memory cache AND to
// %LOCALAPPDATA%\NovaFile\cache, so a picture is decoded exactly once
// ever. "Zoom in Downloads = the whole app freezes" was paint() calling
// IThumbnailProvider synchronously on the UI thread.
// g_tc_ui_shell counts slow lookups run OFF the worker thread: paint()
// must add 0 to it (asserted by the selftest).
static long g_tc_ui_shell = 0;
static __thread bool g_tc_on_worker = false;
static void tc_init(void);
static void tc_shutdown(void);
static void tc_drain(void);
static bool tc_request(const char* path, int w, int h, int bg, int slot);
static HBITMAP tc_disk_lookup(const char* path, int w, int h);
static void tc_disk_store(const char* path, int w, int h, HBITMAP hbm);

// custom folder thumbnails (folder path -> chosen image path), defined
// next to the worker; draw_item_icon() consults it for DIRECTORIES only.
static const char* ct_get(const char* folder);

static int g_sort_key = SORT_NAME;
static int g_sort_dir = 1;

// List content zoom: Ctrl+wheel, the popup buttons or the bottom slider.
// g_zoom is what the layout uses and it EASES towards g_zoom_target every
// frame, so growing/shrinking the icons is smooth instead of jumpy.
static float g_zoom = 0.6f;
static float g_zoom_target = 0.6f;
// While the animated zoom is still easing, the cell and thumb sizes change
// EVERY frame: asking the shell for thumbnails now would mint a fresh cache
// key (and a slow fetch) per frame - the grid visibly "runs" while the
// animation crawls. Type icons are size independent and draw instead;
// thumbnails return the moment the size has settled.
static bool zoom_settling(void) {
    float d = g_zoom_target - g_zoom;
    if (d < 0.0f) d = -d;
    return d > 0.001f;
}
static bool g_size_drag = false;      // mouse held on the vertical zoom track
// Internally the zoom factor still runs to 3.0 (= the old 300%), but it is
// SHOWN as z/3: the slider ends at 100%, and 100% is as big as 300% used
// to be ("large icon" size).
#define ZOOM_MIN 0.45f                // displayed 15%
#define ZOOM_MAX 3.0f                 // displayed 100%

static float quantize_zoom(float z) {              // 5% steps on the DISPLAY
    z = (float)((int)(z * 6.6666667f + 0.5f)) * 0.15f;
    if (z < ZOOM_MIN) z = ZOOM_MIN;
    if (z > ZOOM_MAX) z = ZOOM_MAX;
    return z;
}

static int zoom_percent(float z) {                 // what the label shows
    float d = z / 3.0f * 100.0f + 0.5f;
    if (d > 100.0f) d = 100.0f;
    if (d < 0.0f) d = 0.0f;
    return (int)d;
}

