// ------------------------------------------------------------
// Small helpers
// ------------------------------------------------------------
static void set_status(const char* fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(g_app.status_msg, sizeof(g_app.status_msg), fmt, ap);
    va_end(ap);
    g_status_until = g_app.frame + 240;   // ~4 s in the count slot, then it
}                                         // fades back to the counts

static bool dir_exists(const char* path) {
    if (!path || !path[0]) return false;
    DWORD a = GetFileAttributesA(path);
    return a != INVALID_FILE_ATTRIBUTES && (a & FILE_ATTRIBUTE_DIRECTORY) != 0;
}

// "This PC" is a virtual folder (no real path) - handled specially.
static bool is_this_pc(const char* p) {
    return p && _stricmp(p, THIS_PC) == 0;
}

// ------------------------------------------------------------
// Navigation chain (the Windows shell namespace)
// Desktop is the ROOT, This PC sits under it, drives under This PC.
// The up-arrow and the breadcrumb follow exactly this chain:
//   folder -> ... -> drive -> This PC -> Desktop -> stop (up disabled)
// ------------------------------------------------------------
static char g_desktop_dir[1024] = {0};
static const char* desktop_dir(void) {
    if (!g_desktop_dir[0]) {
        snprintf(g_desktop_dir, sizeof(g_desktop_dir), "%s\\Desktop",
                 platform_get_home_directory());
        if (!dir_exists(g_desktop_dir))
            snprintf(g_desktop_dir, sizeof(g_desktop_dir), "%s",
                     platform_get_home_directory());
    }
    return g_desktop_dir;
}

// True for the Desktop folder itself and everything under it: those paths
// are shown as their own namespace in the address bar ("Desktop > Sub"),
// never as "This PC > C: > Users > ... > Desktop".
static bool path_under_desktop(const char* p) {
    if (!p || !p[0]) return false;
    const char* d = desktop_dir();
    size_t dl = strlen(d);
    if (_strnicmp(p, d, dl) != 0) return false;
    return p[dl] == '\0' || p[dl] == '\\' || p[dl] == '/';
}

static bool is_drive_root(const char* p) {
    return p && p[0] && p[1] == ':' &&
           (p[2] == '\0' || ((p[2] == '\\' || p[2] == '/') && p[3] == '\0'));
}

// Monotonic milliseconds with sub-ms precision (QPC). One shared origin,
// primed single-threaded in main(); workers only ever READ it after that.
// The search engine's timing points and the --bench harness use it.
static double nova_now_ms(void) {
    static LARGE_INTEGER freq, base;
    LARGE_INTEGER now;
    QueryPerformanceCounter(&now);
    if (freq.QuadPart == 0) {                 // first call: pick the origin
        QueryPerformanceFrequency(&freq);
        base = now;
    }
    return (double)(now.QuadPart - base.QuadPart) * 1000.0 /
           (double)freq.QuadPart;
}

// Parent in the chain; false = already at the top (Desktop).
static bool parent_path(const char* path, char* out, size_t n) {
    if (!path || !path[0] || !out || n == 0) return false;
    if (is_this_pc(path)) {
        if (_stricmp(desktop_dir(), path) == 0) return false;  // no loops
        snprintf(out, n, "%s", desktop_dir());
        return true;
    }
    if (is_drive_root(path)) {                    // "D:\" -> This PC
        snprintf(out, n, "%s", THIS_PC);
        return true;
    }
    if (_stricmp(path, desktop_dir()) == 0) return false;      // Desktop = top

    char p[1024];
    snprintf(p, sizeof(p), "%s", path);
    size_t len = strlen(p);
    while (len > 0 && (p[len - 1] == '\\' || p[len - 1] == '/')) p[--len] = '\0';
    char* slash = strrchr(p, '\\');
    if (!slash) slash = strrchr(p, '/');
    if (!slash) return false;
    if (slash == p + 2) p[3] = '\0';             // "C:\sub" -> "C:\"
    else *slash = '\0';
    if (!p[0]) return false;
    snprintf(out, n, "%s", p);
    return true;
}

static bool has_parent(void) {
    char tmp[1024];
    return parent_path(g_app.current_path, tmp, sizeof(tmp));
}

