// ============================================================
// COMMAND / FEATURE REGISTRY  (Settings panel, MASTER PROMPT 5-6)
// ONE table owns every keyboard shortcut, every user-visible
// feature switch and the description of how each of them works.
// Nothing else may hardcode a binding: the dispatch chain, the
// hamburger-menu labels, the gear panel and the persistence all
// read THIS table, so a rebind or an OFF switch is picked up
// everywhere at once and can never drift out of sync.
//   EK_ACTION - has a shortcut that runs an action; `on` gates it
//   EK_OPTION - a real feature value in *var (switch = the value);
//               optional shortcut toggles it, key_gated = the key
//               must die together with the switch
//   EK_DOC    - documentation row only (fixed keys, no state)
// ============================================================

// Feature values behind the option rows (defaults = behaviour today).
static bool g_opt_thumbs = true;      // draw shell thumbnails in the list
static bool g_opt_burst = true;       // fast icon preload after navigation
static bool g_opt_alt_gest = true;    // Alt + corner Back/Forward gesture
static bool g_opt_wheel = true;       // Quick Access wheel on C
static bool g_opt_restore = true;     // Restore Previous Session (startup)

// "Restore Previous Session" engine (defined just before app_init);
// declared here so the command registry's apply callback and the
// navigation hook below can reference it.
static void session_apply(bool on);
static void session_mark_dirty(void);

// Search-box behaviour (Settings -> Search). All in-memory: the filter runs
// over the already-loaded listing, so these change results instantly.
static bool g_search_case = false;    // case-sensitive matching
static bool g_search_broad = true;    // admit contiguous substrings
static bool g_search_word = false;    // (broad off) admit word-start matches
static bool g_search_hl = true;       // highlight matches in the list

// Highlighting is on only when the switch is on and there is a query.
static bool search_hl_active(void) {
    return g_search_hl && g_app.search_buf[0] != '\0';
}

// Modifier bits for a binding (shift is matched only if it is asked for,
// so Ctrl+Tab keeps working as Ctrl+Shift+Tab - see cmd_mods_match).
#define M_CTRL  1u
#define M_SHIFT 2u
#define M_ALT   4u
#define M_WIN   8u            // Windows key: displayed + matched exactly

#define EK_ACTION 0
#define EK_OPTION 1
#define EK_DOC    2

enum {                                  // panel categories (order = column)
    SCAT_GENERAL = 0, SCAT_APPEARANCE, SCAT_NAV, SCAT_FILEOPS, SCAT_THUMBS,
    SCAT_SHORTCUTS, SCAT_GESTURES, SCAT_PANES, SCAT_STARRED, SCAT_PERF,
    SCAT_SEARCH, SCAT_UPDATE, SCAT_ADV, SCAT_COUNT
};
static const char* SCAT_NAMES[SCAT_COUNT] = {
    "General", "Appearance", "Navigation and Tabs", "File Operations",
    "Thumbnails and Previews", "Keyboard Shortcuts",
    "Mouse and Pointer Gestures", "Split Panes and Layout",
    "Starred Items and Quick Access", "Performance", "Search", "Updates",
    "Advanced",
};

typedef struct {
    const char* id;      // persistence key (stable across versions)
    const char* name;    // panel + menu display name
    const char* desc;    // what it does
    const char* how;     // how to use it (NULL = draw the store path)
    int   cat;           // SCAT_* (SCAT_SHORTCUTS rows are collected)
    int   kind;          // EK_ACTION / EK_OPTION / EK_DOC
    int   key,  mods;    // current binding (key 0 = unbound)
    int   dkey, dmods;   // default binding
    int   akey, amods;   // fixed secondary alias (0 = none)
    bool  rebindable;    // the user may change the binding
    bool  has_sw;        // the row shows an ON/OFF switch
    bool  key_gated;     // option: its shortcut dies with the switch
    bool  hidden;        // kept for persistence/behavior, not listed in the UI
    bool* var;           // option value (NULL for actions)
    bool  on;            // action: the shortcut may fire
    bool  don;           // action default (on)
    bool  dval;          // option default value (*var)
    void (*apply)(bool); // option: side effects after *var changed
} SetEnt;

enum {                                  // entry ids (index into g_ents)
    CMD_SET_OPEN = 0, CMD_QUIT, CMD_REFRESH, CMD_HIDDEN, CMD_ESCAPE,
    CMD_THEME, CMD_VIEW, CMD_ZOOM,
    CMD_NEW_TAB, CMD_CYCLE_TAB, CMD_SHIFT_TAB_L, CMD_SHIFT_TAB_R,
    CMD_FOCUS_SEARCH, CMD_FOCUS_ADDR,
    CMD_OPEN, CMD_UP, CMD_HOME, CMD_SEL, CMD_DEEP,
    CMD_RENAME, CMD_DELETE, CMD_COPY, CMD_CUT, CMD_PASTE, CMD_SELECT_ALL,
    CMD_THUMBS, CMD_CTDOC,
    CMD_ALTGEST, CMD_GESTDOC,
    CMD_SPLIT, CMD_CLOSE_PANE,
    CMD_BOOKMARK, CMD_WHEEL, CMD_STARDOC,
    CMD_BURST,
    CMD_STORE,
    CMD_SEARCH_CASE, CMD_SEARCH_BROAD, CMD_SEARCH_WORD, CMD_SEARCH_HL,
    CMD_UPD_SOURCE, CMD_UPD_VER, CMD_UPD_AUTO, CMD_UPD_CHECK,
    CMD_UPD_STATUS, CMD_UPD_RESTART, CMD_UPD_NOTES,
    CMD_RESTORE_SESSION,
    CMD_COUNT
};

